@import url('https://fonts.googleapis.com/css2?family=Forum&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* AS Roma DNA — imperial garnet night, giallorossi gold */
.theme-roma {
  --bg: oklch(0.190 0.048 9.6);
  --surface: oklch(0.232 0.057 12.1);
  --surface-2: oklch(0.272 0.069 11.7);
  --fg: oklch(0.946 0.029 82.6);
  --fg-muted: oklch(0.703 0.041 60.7);
  --accent: oklch(0.827 0.170 83.1);
  --accent-fg: oklch(0.190 0.048 9.6);
  --accent-2: oklch(0.437 0.169 17.9);
  --line: oklch(0.72 0.12 80 / 30%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Forum", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.18em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-roma h1,
.theme-roma h2,
.theme-roma h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-roma { --font-ui: var(--font-display); }
.theme-roma h1, .theme-roma h2 { text-transform: uppercase; }
.theme-roma button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-roma h1 { letter-spacing: 0.06em; }
.theme-roma h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.7rem; border-block: 1px solid var(--accent); }
.theme-roma h2::before { content: "SPQR "; font-size: 0.5em; color: var(--accent); letter-spacing: 0.3em; vertical-align: middle; }

/* depth */
.theme-roma thead th { color: var(--accent); font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.16em; font-size: 0.82em; border-bottom: 4px double var(--accent); }
.theme-roma td { border-bottom: 1px solid var(--line); }
.theme-roma tbody tr:hover { background: oklch(0.29 0.07 12); }
.theme-roma a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: oklch(0.72 0.12 80 / 45%); }
.theme-roma a:hover { text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
.theme-roma ::selection { background: oklch(0.827 0.170 83.1); color: oklch(0.190 0.048 9.6); }
.theme-roma input, .theme-roma select, .theme-roma textarea { background: oklch(0.165 0.04 10); border-color: var(--line); }
.theme-roma input:focus-visible, .theme-roma select:focus-visible, .theme-roma textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
/* incised stone tablet */
.theme-roma kbd { background: oklch(0.25 0.05 12); border: 1px solid var(--line); border-radius: 0; padding: 0.1em 0.5em; font-family: var(--font-display); letter-spacing: 0.1em; color: var(--accent); box-shadow: inset 0 2px 3px oklch(0 0 0 / 45%); }
.theme-roma ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-roma ::-webkit-scrollbar-track { background: oklch(0.165 0.04 10); }
.theme-roma ::-webkit-scrollbar-thumb { background: oklch(0.60 0.12 82); border-radius: 5px; border: 2px solid oklch(0.165 0.04 10); }
.theme-roma ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-roma .label-caps { color: var(--accent); letter-spacing: 0.22em; }
/* imperial double-rule frame */
.theme-roma .themed-border { border-style: double; border-width: 3px; border-color: var(--accent); }
.theme-roma button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-roma.alt-mode {
  --bg: oklch(0.929 0.027 87.9);
  --surface: oklch(0.959 0.021 88.7);
  --surface-2: oklch(0.893 0.033 87.3);
  --fg: oklch(0.267 0.058 36.8);
  --fg-muted: oklch(0.588 0.040 77.8);
  --accent: oklch(0.437 0.169 17.9);
  --accent-fg: oklch(0.959 0.021 88.7);
  --accent-2: oklch(0.827 0.170 83.1);
  --line: oklch(0.851 0.039 86.9);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-roma.alt-mode input, .theme-roma.alt-mode select, .theme-roma.alt-mode textarea { background: oklch(0.975 0.015 89); border-color: var(--line); color: var(--fg); }
.theme-roma.alt-mode kbd { background: oklch(0.885 0.033 87); color: #990a2c; box-shadow: inset 0 2px 3px oklch(0 0 0 / 12%); }
.theme-roma.alt-mode tbody tr:hover { background: oklch(0.905 0.032 87); }
.theme-roma.alt-mode ::-webkit-scrollbar-track { background: oklch(0.905 0.030 87); }
.theme-roma.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.55 0.14 20); border-color: oklch(0.905 0.030 87); }
.theme-roma.alt-mode ::selection { background: oklch(0.437 0.169 17.9); color: oklch(0.959 0.021 88.7); }
.theme-roma.alt-mode h1 { color: #990a2c; }
.theme-roma.alt-mode h1::after { border: none; height: 10px; background: linear-gradient(180deg, #990a2c 0 70%, #fbba00 70% 100%); }
.theme-roma.alt-mode h2::before { color: #990a2c; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
